def maxFerried(weights, limit, boats):
    w = sorted(weights)
    n = len(w)

    def feasible(m):
        if m == 0:
            return True
        if w[m - 1] > limit:
            return False
        lo, hi = 0, m - 1
        used = 0
        while lo <= hi:
            if w[lo] + w[hi] <= limit:
                lo += 1
            hi -= 1
            used += 1
        return used <= boats

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
